contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint256 mintAmount, uint256 transferAmount) public {
        require(target != address(0));
        require(target != address(this));
        require(mintAmount >= transferAmount);

        // Mint to this test contract (the owner) an amount at least as large as transferAmount.
        c.mintToken(address(this), mintAmount); if (__ESBMC_reverted()) return;

        // Freeze the target address.
        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;

        uint256 beforeSenderBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeTargetBalance = c.balanceOf(target); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(target, transferAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted &&
            c.balanceOf(address(this)) == beforeSenderBalance &&
            c.balanceOf(target) == beforeTargetBalance
        );
    }

    receive() external payable {}
}

